// Auto-generated — INNODIA crystal logo as base64 data URL
// Used as Google Maps marker icon (avoids external URL dependency)
export const INNODIA_CRYSTAL_URL = "data:image/png;base64,";

// ── Google Maps teardrop pin with INNODIA crystal in the circular head ────────
//
// ViewBox: 0 0 24 36  — displayed at PIN_W × PIN_H pixels
// The pin tip is at viewBox (12, 36) → display (PIN_W/2, PIN_H)
// Anchor for Google Maps must be (PIN_W/2, PIN_H) — the bottom tip.
//
const PIN_W = 32;
const PIN_H = 48;
const PIN_W_SEL = 40;
const PIN_H_SEL = 60;

const _pinSvg = (color: string, size: [number, number]): string => {
  const [w, h] = size;
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink"` +
    ` width="${w}" height="${h}" viewBox="0 0 24 36">` +
    `<defs><clipPath id="cc"><circle cx="12" cy="12" r="10"/></clipPath></defs>` +
    // Teardrop pin shape
    `<path d="M12 0C5.373 0 0 5.373 0 12c0 7.822 11.026 22.783 11.486 23.382` +
    `.228.292.8.292 1.028 0C12.974 34.783 24 19.822 24 12 24 5.373 18.627 0 12 0z"` +
    ` fill="${color}"/>` +
    // White circle in the head
    `<circle cx="12" cy="12" r="10" fill="white"/>` +
    // Crystal clipped to circle
    `<image x="2" y="2" width="20" height="20" clip-path="url(#cc)" href="${INNODIA_CRYSTAL_URL}"/>` +
    `</svg>`
  );
};

// Normal pin — INNODIA blue
export const INNODIA_PIN_URL = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(_pinSvg("#0072CE", [PIN_W, PIN_H]))}`;
// Selected pin — slightly larger, darker blue
export const INNODIA_PIN_URL_SEL = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(_pinSvg("#004fa3", [PIN_W_SEL, PIN_H_SEL]))}`;

// Sizes and anchors to pass to Google Maps icon object
export const PIN_NORMAL   = { w: PIN_W,     h: PIN_H,     ax: PIN_W / 2,     ay: PIN_H };
export const PIN_SELECTED = { w: PIN_W_SEL, h: PIN_H_SEL, ax: PIN_W_SEL / 2, ay: PIN_H_SEL };
